function syncCustom25DMapPresentation() {
  if (!map) return;

  const container = map.getContainer();
  const tilePane = map.getPane("tilePane");
  const overlayPane = map.getPane("overlayPane");

  if (ENABLE_CUSTOM_25D_MAP) {
    container.classList.add("custom-25d-map-enabled");
    /* Phase 7 checkpoint: Stable daytime 2.5D renderer. Current road/building/shop/zone balance is approved as the safe baseline. Future visual phases must preserve OSM visibility, pin dominance, and ENABLE_CUSTOM_25D_MAP safety. */
    /* Phase 6.7: Contrast hierarchy tune. Slight readability boost only. Must preserve OSM visibility and safe renderer behavior. */
    if (tilePane) {
      tilePane.style.filter = "grayscale(0.75) saturate(0.4) brightness(1.06) contrast(0.86)";
      tilePane.style.opacity = "0.45";
    }
    if (overlayPane) {
      overlayPane.style.opacity = "0.92";
    }
    return;
  }

  container.classList.remove("custom-25d-map-enabled");
  if (tilePane) {
    tilePane.style.filter = "";
    tilePane.style.opacity = "";
  }
  if (overlayPane) {
    overlayPane.style.opacity = "";
  }
}

function initCustom25DMapExperiment() {
  syncCustom25DMapPresentation();
  if (!ENABLE_CUSTOM_25D_MAP || !map || custom25DMapLayer) return;

  /* Custom 2.5D canvas must stay below pins, player marker, capture radius, and UI. */
  map.createPane("custom25DMapPane");
  const pane = map.getPane("custom25DMapPane");
  pane.style.zIndex = "350";
  pane.style.pointerEvents = "none";

  const canvas = L.DomUtil.create("canvas", "custom-25d-map-canvas", pane);
  canvas.style.position = "absolute";
  canvas.style.pointerEvents = "none";

  const redraw = () => drawCustom25DMapCanvas(canvas);
  custom25DMapLayer = { canvas, redraw };

  map.on("moveend zoomend", redraw);
  redraw();
}

function drawCustom25DMapCanvas(canvas) {
  if (!ENABLE_CUSTOM_25D_MAP || !map || !canvas) return;

  let frameViewportSnapshot;
  try {
    frameViewportSnapshot = createCustom25DFrameViewportSnapshot({
      map,
      canvas
    });
  } catch (_error) {
    return {
      outcome: "blocked",
      reasonCode: "FRAME_VIEWPORT_SNAPSHOT_CREATION_FAILED"
    };
  }

  /* Legacy source-lock anchor retained until explicit frame-root snapshot source-lock retirement phase:
  const size = map.getSize();
  const bounds = map.getBounds();
  const topLeft = map.latLngToLayerPoint(bounds.getNorthWest());
  const scale = window.devicePixelRatio || 1;
  canvas.width = Math.max(1, Math.round(size.x * scale));
  canvas.height = Math.max(1, Math.round(size.y * scale));
  canvas.style.width = `${size.x}px`;
  canvas.style.height = `${size.y}px`;
  */
  const size = {
    x: frameViewportSnapshot.logicalWidth,
    y: frameViewportSnapshot.logicalHeight
  };
  const bounds = frameViewportSnapshot;
  const topLeft = frameViewportSnapshot.canvasLayerPosition;
  return drawCustom25DMapCanvasWithFrameSnapshotPrivateImplementation({
    canvas,
    frameViewportSnapshot
  });

  /* Legacy source-lock anchor retained until explicit snapshot-aware draw seam source-lock retirement phase:
  L.DomUtil.setPosition(canvas, topLeft);
  const scale = window.devicePixelRatio || 1;
  canvas.width = Math.max(1, Math.round(size.x * scale));
  canvas.height = Math.max(1, Math.round(size.y * scale));
  canvas.style.width = `${size.x}px`;
  canvas.style.height = `${size.y}px`;
  const ctx = canvas.getContext("2d");
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  ctx.clearRect(0, 0, size.x, size.y);
  drawCustom25DBackground(ctx, size, bounds);
  drawCustom25DZonesLiveCallsite(ctx, bounds, topLeft);
  drawCustom25DBuildingsLiveCallsite(ctx, bounds, topLeft);
  drawCustom25DRoadsLiveCallsite(ctx, bounds, topLeft);
  drawCustom25DTreesLiveCallsite(ctx, bounds, topLeft);
  renderCustomLandmarkLayerLiveCallsite(ctx, bounds);
  */
  /* Legacy source-lock anchor retained until explicit source-lock migration phase:
  drawCustom25DZones(ctx, bounds, topLeft);
  drawCustom25DBuildings(ctx, bounds, topLeft);
  drawCustom25DRoads(ctx, bounds, topLeft);
  drawCustom25DTrees(ctx, size, bounds);
  drawCustom25DLandmarkFoundation(ctx, bounds, topLeft);
  */
}

function setCustom25DMapRoadFeatures(roadWays) {
  custom25DRoadFeatures = Array.isArray(roadWays) ? roadWays : [];

  if (ENABLE_CUSTOM_25D_MAP && custom25DMapLayer?.redraw) {
    custom25DMapLayer.redraw();
  }
}

function setCustom25DMapZoneFeatures(zoneFeatures) {
  custom25DZoneFeatures = Array.isArray(zoneFeatures) ? zoneFeatures : [];

  if (ENABLE_CUSTOM_25D_MAP && custom25DMapLayer?.redraw) {
    custom25DMapLayer.redraw();
  }
}

function setCustom25DMapBuildingFeatures(buildingFeatures) {
  custom25DBuildingFeatures = Array.isArray(buildingFeatures) ? buildingFeatures : [];

  if (ENABLE_CUSTOM_25D_MAP && custom25DMapLayer?.redraw) {
    custom25DMapLayer.redraw();
  }
}

function sanitizeCustom25DCoordinatePair(pair) {
  if (!Array.isArray(pair) || pair.length < 2) {
    return null;
  }

  const latitude = Number(pair[0]);
  const longitude = Number(pair[1]);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
    return null;
  }

  return Object.freeze([
    Number(latitude.toFixed(6)),
    Number(longitude.toFixed(6))
  ]);
}

function sanitizeCustom25DCoordinatePairs(coords) {
  if (!Array.isArray(coords)) {
    return Object.freeze([]);
  }

  return Object.freeze(
    coords
      .map(sanitizeCustom25DCoordinatePair)
      .filter(Boolean)
  );
}

function sanitizeCustom25DPointLike(value) {
  if (!value || typeof value !== "object") {
    return null;
  }

  const lat = Number(value.lat ?? value.latitude);
  const lng = Number(value.lng ?? value.longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    return null;
  }

  return Object.freeze({
    latitude: Number(lat.toFixed(6)),
    longitude: Number(lng.toFixed(6))
  });
}

function sanitizeCustom25DViewportFeatureSource() {
  return Object.freeze({
    schemaId: "GROWGO_CUSTOM25D_CURRENT_VIEWPORT_FEATURE_SOURCE_001",
    zoneFeatures: Object.freeze(
      (Array.isArray(custom25DZoneFeatures) ? custom25DZoneFeatures : []).map(
        (feature) =>
          Object.freeze({
            id: typeof feature?.id === "string" ? feature.id : null,
            zoneType: typeof feature?.zoneType === "string" ? feature.zoneType : null,
            coords: sanitizeCustom25DCoordinatePairs(feature?.coords),
            closed: feature?.closed === true,
            leisure: typeof feature?.leisure === "string" ? feature.leisure : null,
            landuse: typeof feature?.landuse === "string" ? feature.landuse : null,
            natural: typeof feature?.natural === "string" ? feature.natural : null,
            waterway: typeof feature?.waterway === "string" ? feature.waterway : null,
            boundary: typeof feature?.boundary === "string" ? feature.boundary : null
          })
      )
    ),
    buildingFeatures: Object.freeze(
      (Array.isArray(custom25DBuildingFeatures)
        ? custom25DBuildingFeatures
        : []
      ).map((feature) =>
        Object.freeze({
          id: typeof feature?.id === "string" ? feature.id : null,
          coords: sanitizeCustom25DCoordinatePairs(feature?.coords),
          center: sanitizeCustom25DPointLike(feature?.center),
          buildingType:
            typeof feature?.buildingType === "string" ? feature.buildingType : null,
          shopTag: typeof feature?.shopTag === "string" ? feature.shopTag : null,
          amenity: typeof feature?.amenity === "string" ? feature.amenity : null,
          office: typeof feature?.office === "string" ? feature.office : null,
          cuisine: typeof feature?.cuisine === "string" ? feature.cuisine : null,
          tourism: typeof feature?.tourism === "string" ? feature.tourism : null,
          leisure: typeof feature?.leisure === "string" ? feature.leisure : null,
          landuse: typeof feature?.landuse === "string" ? feature.landuse : null,
          buildingArea: Number.isFinite(Number(feature?.buildingArea))
            ? Number(feature.buildingArea)
            : null,
          nearCoast: feature?.nearCoast === true
        })
      )
    ),
    roadWays: Object.freeze(
      (Array.isArray(custom25DRoadFeatures) ? custom25DRoadFeatures : []).map((road) =>
        Object.freeze({
          id:
            typeof road?.id === "string" || typeof road?.id === "number"
              ? String(road.id)
              : null,
          highway: typeof road?.highway === "string" ? road.highway : null,
          coords: sanitizeCustom25DCoordinatePairs(road?.coords)
        })
      )
    )
  });
}

function getCustom25DCurrentViewportFeatureSource() {
  return sanitizeCustom25DViewportFeatureSource();
}

function custom25DSeedFromBounds(bounds) {
  const center = bounds.getCenter();
  return Math.abs(Math.sin(center.lat * 12.9898 + center.lng * 78.233) * 43758.5453);
}

function custom25DRandom(seed, index) {
  return Math.abs(Math.sin(seed + index * 127.1) * 10000) % 1;
}

function custom25DPoint(size, seed, index) {
  return {
    x: custom25DRandom(seed, index) * size.x,
    y: custom25DRandom(seed, index + 41) * size.y
  };
}

function drawCustom25DBackground(ctx, size) {
  const bg = ctx.createLinearGradient(0, 0, size.x, size.y);
  bg.addColorStop(0, "rgba(241, 246, 226, 0.25)");
  bg.addColorStop(0.48, "rgba(229, 238, 213, 0.35)");
  bg.addColorStop(1, "rgba(214, 227, 194, 0.25)");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, size.x, size.y);
}

function shouldDrawZoneDetailsAtZoom(zoom, detailLevel = "medium") {
  if (detailLevel === "low") return zoom >= 15;
  if (detailLevel === "high") return zoom >= 18;
  return zoom >= 16.5;
}

function getZoneStyleForFeature(featureType, zoom) {
  const styles = {
    park: {
      fill: "rgba(125, 198, 108, 0.40)",
      edge: "rgba(76, 144, 68, 0.32)",
      inner: "rgba(196, 233, 173, 0.11)"
    },
    grass: {
      fill: "rgba(154, 203, 130, 0.22)",
      edge: "rgba(108, 156, 89, 0.12)",
      inner: "rgba(201, 228, 178, 0.04)"
    },
    water: {
      fill: "rgba(92, 181, 221, 0.37)",
      edge: "rgba(56, 132, 192, 0.34)",
      inner: "rgba(204, 239, 251, 0.11)"
    },
    beach: {
      fill: "rgba(239, 221, 165, 0.34)",
      edge: "rgba(195, 171, 111, 0.22)",
      inner: "rgba(251, 239, 206, 0.11)"
    },
    wetland: {
      fill: "rgba(121, 176, 152, 0.24)",
      edge: "rgba(82, 133, 112, 0.18)",
      inner: "rgba(174, 214, 193, 0.06)"
    },
    sports: {
      fill: "rgba(122, 196, 114, 0.22)",
      edge: "rgba(78, 142, 80, 0.14)",
      inner: "rgba(207, 236, 192, 0.06)"
    }
  };

  const base = styles[featureType] || styles.grass;
  return {
    ...base,
    lineWidth: zoom >= 18 ? 2.2 : zoom >= 16.5 ? 1.6 : 1.1
  };
}

function projectCustom25DZonePoints(coords, topLeft) {
  if (!Array.isArray(coords) || !coords.length) return [];

  return coords.map(([lat, lng]) => {
    const point = map.latLngToLayerPoint([lat, lng]);
    return {
      x: point.x - topLeft.x,
      y: point.y - topLeft.y
    };
  });
}

function drawCustom25DZone(ctx, points, style, closed = true) {
  if (!Array.isArray(points) || points.length < 2) return;

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i += 1) {
    ctx.lineTo(points[i].x, points[i].y);
  }
  if (closed) ctx.closePath();

  if (closed) {
    ctx.fillStyle = style.fill;
    ctx.fill();
    ctx.strokeStyle = style.edge;
    ctx.lineWidth = style.lineWidth;
    ctx.stroke();
  } else {
    ctx.strokeStyle = style.fill;
    ctx.lineWidth = Math.max(4, style.lineWidth * 3.2);
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.stroke();
  }
  ctx.restore();
}

function drawWaterTexture(ctx, points, zoom, closed) {
  if (!shouldDrawZoneDetailsAtZoom(zoom, "medium") || !Array.isArray(points) || points.length < 2) return;

  const bounds = getProjectedBounds(points);
  const spacing = zoom >= 18 ? 22 : 30;

  ctx.save();
  ctx.strokeStyle = "rgba(255, 255, 255, 0.24)";
  ctx.lineWidth = 1.12;
  if (closed) {
    clipToProjectedPolygon(ctx, points);
  }

  for (let y = bounds.minY + 10; y < bounds.maxY; y += spacing) {
    ctx.beginPath();
    for (let x = bounds.minX - 12; x <= bounds.maxX + 12; x += 22) {
      const waveY = y + Math.sin((x + y) * 0.032) * 2.1;
      if (x === bounds.minX - 12) ctx.moveTo(x, waveY);
      else ctx.lineTo(x, waveY);
    }
    ctx.stroke();
  }
  ctx.restore();
}

function drawBeachDetails(ctx, points, zoom) {
  if (!shouldDrawZoneDetailsAtZoom(zoom, "high") || !Array.isArray(points) || points.length < 3) return;

  const bounds = getProjectedBounds(points);
  ctx.save();
  clipToProjectedPolygon(ctx, points);
  ctx.fillStyle = "rgba(255, 246, 214, 0.24)";

  for (let i = 0; i < 10; i += 1) {
    const x = bounds.minX + ((i * 41) % Math.max(40, bounds.maxX - bounds.minX + 1));
    const y = bounds.minY + ((i * 27) % Math.max(40, bounds.maxY - bounds.minY + 1));
    ctx.fillRect(x, y, 2, 2);
  }
  ctx.restore();
}

function drawGrassTexture(ctx, points, zoom, style) {
  if (!shouldDrawZoneDetailsAtZoom(zoom, "medium") || !Array.isArray(points) || points.length < 3) return;

  const bounds = getProjectedBounds(points);
  ctx.save();
  clipToProjectedPolygon(ctx, points);
  ctx.fillStyle = style.inner;

  const spacing = zoom >= 18 ? 22 : 32;
  for (let y = bounds.minY + 10; y < bounds.maxY; y += spacing) {
    ctx.fillRect(bounds.minX, y, Math.max(20, bounds.maxX - bounds.minX), zoom >= 18 ? 1.6 : 1);
  }
  ctx.restore();
}

function drawParkDetails(ctx, points, zoom) {
  if (!shouldDrawZoneDetailsAtZoom(zoom, "medium") || !Array.isArray(points) || points.length < 3) return;

  const bounds = getProjectedBounds(points);
  ctx.save();
  clipToProjectedPolygon(ctx, points);

  if (shouldDrawZoneDetailsAtZoom(zoom, "high")) {
    ctx.strokeStyle = "rgba(248, 240, 204, 0.24)";
    ctx.lineWidth = 1;
    for (let y = bounds.minY + 18; y < bounds.maxY; y += 54) {
      ctx.beginPath();
      ctx.moveTo(bounds.minX, y);
      ctx.quadraticCurveTo((bounds.minX + bounds.maxX) * 0.5, y + 6, bounds.maxX, y - 3);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function drawSportsFieldDetails(ctx, points, zoom) {
  if (!shouldDrawZoneDetailsAtZoom(zoom, "high") || !Array.isArray(points) || points.length < 3) return;

  const bounds = getProjectedBounds(points);
  ctx.save();
  clipToProjectedPolygon(ctx, points);
  ctx.strokeStyle = "rgba(255, 255, 255, 0.28)";
  ctx.lineWidth = 1.2;
  ctx.strokeRect(bounds.minX + 8, bounds.minY + 8, Math.max(0, bounds.maxX - bounds.minX - 16), Math.max(0, bounds.maxY - bounds.minY - 16));
  ctx.restore();
}

function drawWetlandDetails(ctx, points, zoom) {
  if (!shouldDrawZoneDetailsAtZoom(zoom, "high") || !Array.isArray(points) || points.length < 3) return;

  const bounds = getProjectedBounds(points);
  ctx.save();
  clipToProjectedPolygon(ctx, points);
  ctx.strokeStyle = "rgba(89, 134, 104, 0.28)";
  ctx.lineWidth = 1;

  for (let x = bounds.minX + 10; x < bounds.maxX; x += 18) {
    ctx.beginPath();
    ctx.moveTo(x, bounds.maxY);
    ctx.lineTo(x - 2, bounds.maxY - 9);
    ctx.lineTo(x + 1, bounds.maxY - 17);
    ctx.stroke();
  }
  ctx.restore();
}

function getProjectedBounds(points) {
  return points.reduce((acc, point) => ({
    minX: Math.min(acc.minX, point.x),
    minY: Math.min(acc.minY, point.y),
    maxX: Math.max(acc.maxX, point.x),
    maxY: Math.max(acc.maxY, point.y)
  }), {
    minX: Number.POSITIVE_INFINITY,
    minY: Number.POSITIVE_INFINITY,
    maxX: Number.NEGATIVE_INFINITY,
    maxY: Number.NEGATIVE_INFINITY
  });
}

function clipToProjectedPolygon(ctx, points) {
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i += 1) {
    ctx.lineTo(points[i].x, points[i].y);
  }
  ctx.closePath();
  ctx.clip();
}

function createCustom25DZonesLiveViewportProjection(bounds, topLeft) {
  /* Legacy source-lock anchor retained until explicit frame-root snapshot source-lock retirement phase:
  const frozenZoom = map.getZoom();
  const frozenTopLeft = topLeft || map.latLngToLayerPoint(bounds.getNorthWest());
  insideSnapshotBounds: bounds.contains([latitude, longitude]) === true
  */
  const frameViewportSnapshot =
    bounds?.schemaId === CUSTOM_25D_FRAME_VIEWPORT_SNAPSHOT_SCHEMA_ID &&
    bounds?.snapshotCreated === true
      ? bounds
      : null;
  const frozenZoom = Number(frameViewportSnapshot?.zoom);
  const frozenTopLeft = frameViewportSnapshot?.canvasLayerPosition || topLeft;

  return {
    getZoom() {
      return frozenZoom;
    },
    projectCoordinateToCanvasPoint({ latitude, longitude }) {
      const point = map.latLngToLayerPoint([latitude, longitude]);
      return {
        canvasPoint: {
          x: point.x - frozenTopLeft.x,
          y: point.y - frozenTopLeft.y
        },
        insideSnapshotBounds:
          frameViewportSnapshot?.contains([latitude, longitude]) === true
      };
    }
  };
}

function projectCustom25DZonePointsWithViewport(coords, viewportProjection) {
  if (!Array.isArray(coords) || !coords.length) {
    return {
      outcome: "blocked",
      reasonCode: "ZONE_COORDS_INVALID",
      points: [],
      insideViewport: false,
      projectionCount: 0
    };
  }

  const points = [];
  let projectionCount = 0;
  let insideViewport = false;

  for (const coordinate of coords) {
    if (!Array.isArray(coordinate) || coordinate.length < 2) {
      return {
        outcome: "blocked",
        reasonCode: "ZONE_COORDINATE_INVALID",
        points: [],
        insideViewport: false,
        projectionCount
      };
    }

    const latitude = Number(coordinate[0]);
    const longitude = Number(coordinate[1]);
    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
      return {
        outcome: "blocked",
        reasonCode: "ZONE_COORDINATE_INVALID",
        points: [],
        insideViewport: false,
        projectionCount
      };
    }

    const projected = viewportProjection.projectCoordinateToCanvasPoint({
      latitude,
      longitude
    });
    projectionCount += 1;

    const canvasPoint = projected?.canvasPoint;
    if (
      !canvasPoint ||
      !Number.isFinite(Number(canvasPoint.x)) ||
      !Number.isFinite(Number(canvasPoint.y))
    ) {
      return {
        outcome: "blocked",
        reasonCode: "ZONE_PROJECTION_INVALID",
        points: [],
        insideViewport: false,
        projectionCount
      };
    }

    if (projected.insideSnapshotBounds === true) {
      insideViewport = true;
    }

    points.push({
      x: Number(canvasPoint.x),
      y: Number(canvasPoint.y)
    });
  }

  return {
    outcome: "ready",
    reasonCode: "ZONE_POINTS_PROJECTED",
    points,
    insideViewport,
    projectionCount
  };
}

function drawCustom25DZonesViewportInjected(ctx, zoneFeatures, viewportProjection) {
  if (!Array.isArray(zoneFeatures) || !zoneFeatures.length) {
    return {
      outcome: "noop",
      reasonCode: "ZONE_FEATURES_EMPTY"
    };
  }

  const zoom = Number(viewportProjection.getZoom());
  if (!Number.isFinite(zoom)) {
    return {
      outcome: "blocked",
      reasonCode: "ZONE_VIEWPORT_ZOOM_INVALID"
    };
  }

  const zonePriority = {
    grass: 1,
    sports: 2,
    park: 3,
    wetland: 4,
    beach: 5,
    water: 6
  };

  const projectedEntries = [];

  for (const feature of zoneFeatures) {
    if (!Array.isArray(feature?.coords) || feature.coords.length < 2) {
      continue;
    }

    let projection;
    try {
      projection = projectCustom25DZonePointsWithViewport(
        feature.coords,
        viewportProjection
      );
    } catch (error) {
      return {
        outcome: "blocked",
        reasonCode: "ZONE_PROJECTION_FAILED",
        error
      };
    }

    if (projection.outcome !== "ready") {
      return projection;
    }

    if (!projection.insideViewport || projection.points.length < 2) {
      continue;
    }

    projectedEntries.push({
      feature,
      points: projection.points
    });
  }

  projectedEntries
    .sort((a, b) => (zonePriority[a.feature.zoneType] || 0) - (zonePriority[b.feature.zoneType] || 0))
    .forEach(({ feature, points }) => {
      const style = getZoneStyleForFeature(feature.zoneType, zoom);
      drawCustom25DZone(ctx, points, style, feature.closed !== false);

      if (feature.zoneType === "water") {
        drawWaterTexture(ctx, points, zoom, feature.closed !== false);
      } else if (feature.zoneType === "beach") {
        drawBeachDetails(ctx, points, zoom);
      } else if (feature.zoneType === "park") {
        drawParkDetails(ctx, points, zoom);
      } else if (feature.zoneType === "grass") {
        drawGrassTexture(ctx, points, zoom, style);
      } else if (feature.zoneType === "sports") {
        drawSportsFieldDetails(ctx, points, zoom);
      } else if (feature.zoneType === "wetland") {
        drawWetlandDetails(ctx, points, zoom);
      }
    });

  return {
    outcome: "success",
    reasonCode: "ZONES_DRAWN_WITH_VIEWPORT",
    zoom
  };
}

function drawCustom25DZonesLiveCallsite(ctx, bounds, topLeft) {
  if (!Array.isArray(custom25DZoneFeatures) || !custom25DZoneFeatures.length) return;

  let viewportProjection;
  try {
    viewportProjection = createCustom25DZonesLiveViewportProjection(bounds, topLeft);
  } catch (_error) {
    return {
      outcome: "blocked",
      reasonCode: "ZONE_VIEWPORT_CREATION_FAILED"
    };
  }

  try {
    return drawCustom25DZonesViewportInjected(
      ctx,
      custom25DZoneFeatures,
      viewportProjection
    );
  } catch (_error) {
    return {
      outcome: "blocked",
      reasonCode: "ZONE_LAYER_DRAW_FAILED"
    };
  }
}

function drawCustom25DZones(ctx, bounds, topLeft) {
  if (!Array.isArray(custom25DZoneFeatures) || !custom25DZoneFeatures.length) return;

  const zoom = map.getZoom();
  const zonePriority = {
    grass: 1,
    sports: 2,
    park: 3,
    wetland: 4,
    beach: 5,
    water: 6
  };

  custom25DZoneFeatures
    .filter((feature) => Array.isArray(feature?.coords) && feature.coords.length >= 2)
    .filter((feature) => feature.coords.some(([lat, lng]) => bounds.contains([lat, lng])))
    .sort((a, b) => (zonePriority[a.zoneType] || 0) - (zonePriority[b.zoneType] || 0))
    .forEach((feature) => {
      const points = projectCustom25DZonePoints(feature.coords, topLeft);
      if (points.length < 2) return;

      const style = getZoneStyleForFeature(feature.zoneType, zoom);
      drawCustom25DZone(ctx, points, style, feature.closed !== false);

      if (feature.zoneType === "water") {
        drawWaterTexture(ctx, points, zoom, feature.closed !== false);
      } else if (feature.zoneType === "beach") {
        drawBeachDetails(ctx, points, zoom);
      } else if (feature.zoneType === "park") {
        drawParkDetails(ctx, points, zoom);
      } else if (feature.zoneType === "grass") {
        drawGrassTexture(ctx, points, zoom, style);
      } else if (feature.zoneType === "sports") {
        drawSportsFieldDetails(ctx, points, zoom);
      } else if (feature.zoneType === "wetland") {
        drawWetlandDetails(ctx, points, zoom);
      }
    });
}

function shouldDrawBuildingAtZoom(zoom) {
  return zoom >= 16.2;
}

