    consumerName,
    accepted,
    denied,
    deterministic: true,
    manualCallOnly: true,
    sceneId:
      scene && typeof scene.sceneId === "string" ? scene.sceneId : "unknown-scene-id",
    sceneType:
      scene && typeof scene.sceneType === "string"
